/*
 Problem: 146. LRU Cache
 Language: cpp
 Runtime: 23 ms (44.06%)
 Memory: 47.9 MB (82.18%)
 Tags: Design, Doubly-Linked List, Hash Table, Linked List
*/
class LRUCache {
    int cap;
    list<pair<int, int>> l;
    unordered_map<int, list<pair<int, int>>::iterator> mp;

public:
    LRUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        if (!mp.count(key))
            return -1;

        auto it = mp[key];
        l.splice(l.begin(), l, it);
        return it->second;
    }

    void put(int key, int value) {
        if (mp.count(key)) {
            auto it = mp[key];
            it->second = value;
            l.splice(l.begin(), l, it);
            return;
        }

        l.push_front({key, value});
        mp[key] = l.begin();

        if (l.size() > cap) {
            mp.erase(l.back().first);
            l.pop_back();
        }
    }
};

